const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'../outputs/dracula-design-office');
const edit=(p,fn)=>{p=path.join(root,p);fs.writeFileSync(p,fn(fs.readFileSync(p,'utf8')))};
edit('backend/app/api/admin/resources/_common.py',s=>s.replace('LOCALES: tuple[str, ...] = ("ro", "en", "de", "hu", "bg", "el")','from ....dracula_locales import LOCALES'));
edit('backend/app/api/admin/resources/settings.py',s=>s.replace('from .... import theme_schedule','from .... import theme_schedule\nfrom ....dracula_locales import valid_locale').replace('sorted(set(languages) - set(LOCALES))','sorted(x for x in languages if not valid_locale(x))').replace('sorted(set(fields["languages"] or []) - set(LOCALES))','sorted(x for x in (fields["languages"] or []) if not valid_locale(x))'));
edit('backend/app/api/admin/resources/products.py',s=>s.replace('unknown = sorted(set(value) - set(LOCALES))','unknown = sorted(k for k in value if k not in LOCALES)'));
edit('backend/app/config.py',s=>s.replace('"cesiro_admin_rt"','"dracula_admin_rt"').replace('"DEFAULT_TENANT", "cesiro1"','"DEFAULT_TENANT", "dracula-design"'));
edit('backend/app/api/storefront.py',s=>s.replace('CART_COOKIE = "eva_cart"','CART_COOKIE = "dracula_cart"').replace('SESSION_COOKIE = "eva_session"','SESSION_COOKIE = "dracula_session"').replace('ORDER_COOKIE = "eva_orders"','ORDER_COOKIE = "dracula_orders"').replace('CSRF_COOKIE = "eva_csrf"','CSRF_COOKIE = "dracula_csrf"').replace('    from ..factory import request_tenant\n\n    return request_tenant()','    return get_settings().default_tenant').replace('    if lang in cms.LANGS:\n        return lang','    from ..dracula_locales import enabled_locales\n    if lang in enabled_locales():\n        return lang').replace('locale = data.lang if data.lang in ("ro", "en", "de", "hu", "bg", "el") else "ro"','locale = _locale()'));
edit('frontend/src/types/common.ts',s=>s.replace("export const LANGUAGES = ['ro', 'en', 'de', 'hu', 'bg', 'el'] as const;\nexport type Language = (typeof LANGUAGES)[number];","export const LANGUAGES: string[] = ['ro', 'en', 'de'];\nexport type Language = string;\nexport function setLanguages(values: string[]) { LANGUAGES.splice(0, LANGUAGES.length, ...values); }").replace("return { ro: '', en: '', de: '', hu: '', bg: '', el: '' };","return Object.fromEntries(LANGUAGES.map(code => [code, '']));"));
edit('frontend/src/main.tsx',s=>s.replace("import App from './app/App';","import App from './app/App';\nimport { setLanguages } from './types/common';").replace('createRoot(container).render(','async function boot() {\n  try { const response = await fetch(\'/api/public/brand\'); if(response.ok) {const brand=await response.json(); if(Array.isArray(brand.languages)&&brand.languages.length)setLanguages(brand.languages);} } catch { /* auth error screen remains available */ }\ncreateRoot(container!).render(').replace(/\);\s*$/,');\n}\nvoid boot();\n'));
edit('frontend/src/features/settings/SettingsPage.tsx',s=>s.replace('  LANGUAGES,','  LANGUAGES,\n  setLanguages,').replace("const [tab, setTab] = useState('identity');","const [tab, setTab] = useState('identity');\n  const [newLocale, setNewLocale] = useState('');").replace("{tab === 'locales' && (\n        <div className=\"card\">","{tab === 'locales' && (\n        <div className=\"card\">\n          <div className=\"field-row\"><TextField id=\"new-locale\" label=\"Cod limbă nouă (fr, it, es, pt-BR)\" value={newLocale} onChange={e=>setNewLocale(e.target.value)} /><button className=\"btn\" type=\"button\" onClick={()=>{const code=newLocale.trim(); if(!/^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$/.test(code))return;setLanguages([...new Set([...LANGUAGES,code])]);setDraft({...draft,languages:[...new Set([...draft.languages,code])]});setNewLocale('');}}>Adaugă limba</button></div>"));
edit('frontend/src/shell/AdminLayout.tsx',s=>s.replace('cesiro.admin.ui','dracula.admin.ui'));
edit('frontend/index.html',s=>s.replace(/CESIRO/gi,'Dracula Design'));
edit('frontend/package.json',s=>s.replace('cesiro1-admin','dracula-design-admin'));
edit('frontend/package-lock.json',s=>s.replaceAll('cesiro1-admin','dracula-design-admin'));
const publicDir=path.join(root,'backend/public');fs.mkdirSync(publicDir,{recursive:true});
fs.cpSync(path.join(root,'dist/assets'),path.join(publicDir,'assets'),{recursive:true});
fs.copyFileSync(path.join(root,'dist/styles.css'),path.join(publicDir,'styles.css'));
console.log('Admin and API adapted; original assets copied.');
